// @ts-nocheck -- type-checked in the motion-film project, not here.
// Generated by scripts/sync-film.mjs from motion-film/src/data/schema.ts. Edit it there, then run `npm run sync:film`.
import { z } from "zod";

/**
 * Everything a viewer reads on screen lives here, so it can be edited in Remotion Studio's
 * props panel (or passed with --props=file.json) without touching scene code.
 */
export const eventSchema = z.object({
  id: z.string(),
  title: z.string(),
  /** ISO date (YYYY-MM-DD). Empty string = to be confirmed; the scene then hides the date line. */
  date: z.string(),
  time: z.string(),
  venue: z.string(),
});

export const creditSchema = z.object({
  name: z.string(),
  /** Relationship label. Leave empty when not provided — never invent one. */
  role: z.string(),
});

export const invitationSchema = z.object({
  bride: z.string(),
  groom: z.string(),
  family: z.string(),
  invitationLine: z.string(),
  rsvpUrl: z.string(),
  rsvpLabel: z.string(),
  events: z.object({
    engagement: eventSchema,
    haldi: eventSchema,
    mehendi: eventSchema,
    sangeet: eventSchema,
    weddingDay: z.object({
      date: z.string(),
      venue: z.string(),
      items: z.array(eventSchema.pick({ id: true, title: true, time: true })),
    }),
    reception: eventSchema,
  }),
  credits: z.array(
    z.object({
      heading: z.string(),
      names: z.array(creditSchema),
    }),
  ),
});

export type Invitation = z.infer<typeof invitationSchema>;
export type WeddingEvent = z.infer<typeof eventSchema>;
